using System;
using WoWProbe;

class FishingSessionTests
{
    sealed class Fake:IInputBackend
    {public bool Focus=true,Emergency,Held,FailDown,FailUp;public int Downs,Ups,ModifierUps;public ushort HeldModifier,LastKey;public Action OnDown;public bool IsTargetForeground(){return Focus;}public bool IsEmergencyPressed(){return Emergency;}public bool IsKeyAlreadyDown(ushort key){return Held||HeldModifier!=0&&key==HeldModifier;}public void KeyDown(ushort key){Downs++;LastKey=key;if(OnDown!=null)OnDown();if(FailDown)throw new Exception("partial down");}public void KeyUp(ushort key){Ups++;if(key==16||key==17||key==18)ModifierUps++;if(FailUp)throw new Exception("release failure");}}
    static int passed,failed;static void Test(string n,Action a){try{a();passed++;Console.WriteLine("PASS "+n);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+n+": "+ex.Message);}}
    static void Assert(bool b,string why){if(!b)throw new Exception(why);}
    static FishingPlan Plan(){var p=new FishingPlan{Name="TEST",Facing=0,Spot=new Waypoint{X=.5,Y=.5},Calibration=new NavigationCalibration{MapId=42,MapMode=2,Zone="TEST",Confirmed=true}};p.Settings.BindingsConfirmed=p.Settings.AutoLootConfirmed=p.Settings.AudioConfirmed=true;return p;}
    static FishingObservation Observation(long time)
    {return new FishingObservation{CapturedAtMs=time,AudioReady=true,Game=new OperationObservation{Fresh=true,Sequence=1,MapId=42,FreeSlotsKnown=true,FreeSlots=10,GeometryKnown=true,ClientWidth=1920,ClientHeight=1080,CursorKnown=true,CursorEmpty=true,ConfirmationKnown=true,MerchantKnown=true,IncomingResurrectionKnown=true,InventoryKnown=true,InventoryEventsKnown=true,InventoryCycleKnown=true,Farm=new FarmObservation{Fresh=true,Sequence=1,KnownCore=true,MapId=42,MapMode=2,Zone="TEST",X=.5,Y=.5,Facing=0,Health=100,Power=100,PowerType=0,CastingKnown=true,LootKnown=true,LootEventsKnown=true,CastEventsKnown=true}}};}
    static FishingObservation Sequenced(long time,ref int sequence)
    {var o=Observation(time);o.Game.Sequence=o.Game.Farm.Sequence=++sequence;return o;}
    static FishingPlan VendorPlan(bool nearby=false)
    {var p=Plan();p.Settings.EnableVendor=p.Settings.AutoSellConfirmed=true;p.Vendor=new BattleTarget{Name="Saved merchant",NameHash=TargetCatalog.HashName("Saved merchant"),Kind="npc"};p.VendorRoute=new RouteDocument{RouteId="session-vendor",Name="TEST",RouteType="vendor_return",MapId=42,MapMode=2,Zone="TEST"};p.VendorRoute.Points.Add(p.Spot.Clone());p.VendorRoute.Points.Add(new Waypoint{X=.5,Y=nearby?.4996:.49,Tolerance=.001});return p;}
    static FishingObservation Full(long time,ref int sequence)
    {var o=Sequenced(time,ref sequence);o.Game.FreeSlots=0;o.Game.Farm.BagFull=true;o.LastBagVoiceAtMs=o.LastBagTextAtMs=5000;o.BagVoiceConfidence=o.BagTextConfidence=.98;return o;}
    static FishingCheckpoint SellingCheckpoint(FishingPlan p)
    {return new FishingCheckpoint{PlanFingerprint=p.Fingerprint(),Phase="VendorWait",RouteIndex=p.VendorRoute.Points.Count,VendorSlotsBefore=0,VendorInventoryRevision=10,VendorTargetToken=11,VendorNameHash=p.Vendor.NameHash,MerchantObserved=true};}
    static FishingObservation SellingObservation(FishingPlan p,long time,bool open,bool cleared)
    {var o=Observation(time);var g=o.Game;var f=g.Farm;f.Y=p.VendorRoute.Points[p.VendorRoute.Points.Count-1].Y;f.TargetExists=f.TargetIdentityKnown=f.NameHashKnown=f.AttackabilityKnown=f.TargetDeadKnown=true;f.TargetToken=11;f.TargetNameHash=p.Vendor.NameHash;f.TargetHealth=100;g.MerchantOpen=open;g.MerchantTargetToken=11;g.MerchantNameHash=p.Vendor.NameHash;g.FreeSlots=cleared?8:0;g.InventoryRevision=cleared?11u:10u;return o;}
    static void Reject(Action a){bool rejected=false;try{a();}catch(InvalidOperationException){rejected=true;}Assert(rejected,"expected rejection");}
    static int Main()
    {
        Test("manual fishing binding and Auto Loot confirmations are mandatory",delegate{var f=new Fake();var p=Plan();p.Settings.AutoLootConfirmed=false;var s=new FishingSession(f,()=>0,()=>Observation(0),null,new InputFailureLatch());Reject(()=>s.Start(p));Assert(f.Downs==0,"unconfirmed input");});
        Test("checkpoint recovery cannot arm without explicit confirmation",delegate{var p=Plan();var cp=new FishingCheckpoint{PlanFingerprint=p.Fingerprint(),Phase="WaitBite"};var f=new Fake();var s=new FishingSession(f,()=>0,()=>Observation(0),null,new InputFailureLatch());Reject(()=>s.Start(p,cp,false));Assert(!s.IsActive&&f.Downs==0,"unconfirmed checkpoint armed");});
        Test("confirmed stationary checkpoint discards its prior cast and pending reel",delegate{var p=Plan();var cp=new FishingCheckpoint{PlanFingerprint=p.Fingerprint(),Phase="LootWait"};var f=new Fake();long time=1000;var s=new FishingSession(f,()=>time,()=>{var o=Observation(time);o.LastBiteAtMs=900;o.BiteConfidence=.99;return o;},null,new InputFailureLatch());s.Start(p,cp,true);Assert(s.Status=="Countdown"&&s.EngineStatus=="Ready"&&s.Casts==0&&s.Reels==0&&f.Downs==0,"old checkpoint action was restored");time=6000;s.Tick();Assert(f.Downs==1&&s.Casts==1&&s.Reels==0,"checkpoint did not start a new cast after countdown");s.Stop("cleanup");});
        Test("confirmed return checkpoint preserves its recorded direction and index",delegate{var p=VendorPlan();var cp=new FishingCheckpoint{PlanFingerprint=p.Fingerprint(),Phase="ReturnSpot",RouteIndex=1};var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>{var o=Observation(time);o.Game.Farm.Y=.49;return o;},null,new InputFailureLatch());s.Start(p,cp,true);Assert(s.EngineStatus=="ReturnSpot"&&s.CurrentCheckpoint.RouteIndex==1&&f.Downs==0,"return checkpoint was flattened to a fresh fishing start");time=5000;s.Tick();Assert(s.IsActive&&s.IsHolding&&f.Downs==1&&s.Casts==0,"return route did not resume after countdown");s.Stop("cleanup");});
        Test("return checkpoint at the wrong recorded location cannot arm",delegate{var p=VendorPlan();var cp=new FishingCheckpoint{PlanFingerprint=p.Fingerprint(),Phase="ReturnSpot",RouteIndex=1};var f=new Fake();var s=new FishingSession(f,()=>0,()=>Observation(0),null,new InputFailureLatch());Reject(()=>s.Start(p,cp,true));Assert(!s.IsActive&&f.Downs==0,"mismatched return location armed");});
        Test("open selling checkpoint retains its original inventory baseline without another F",delegate{var p=VendorPlan(true);var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>SellingObservation(p,time,true,false),null,new InputFailureLatch());s.Start(p,SellingCheckpoint(p),true);time=5000;s.Tick();Assert(s.IsActive&&s.EngineStatus=="VendorWait"&&f.Downs==0,"open restored merchant was interacted with again");Assert(s.CurrentCheckpoint.VendorSlotsBefore==0&&s.CurrentCheckpoint.VendorInventoryRevision==10,"original selling baseline was discarded");s.Stop("cleanup");});
        Test("selling completed while paused returns without F or Escape on an already closed window",delegate{var p=VendorPlan(true);var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>SellingObservation(p,time,false,true),null,new InputFailureLatch());s.Start(p,SellingCheckpoint(p),true);time=5000;s.Tick();Assert(s.IsActive&&s.EngineStatus=="ReturnSpot"&&f.Downs==0,"completed closed merchant received an unnecessary key");s.Stop("cleanup");});
        Test("selling completed in the same open window closes with Escape instead of another F",delegate{var p=VendorPlan(true);var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>SellingObservation(p,time,true,true),null,new InputFailureLatch());s.Start(p,SellingCheckpoint(p),true);time=5000;s.Tick();Assert(s.IsActive&&s.EngineStatus=="ReturnSpot"&&f.Downs==1&&f.LastKey==0x1B,"restored completed sale did not close the same merchant exactly once");s.Stop("cleanup");});
        Test("stationary fishing still requires confirmed facing calibration",delegate{var f=new Fake();var p=Plan();p.Calibration.Confirmed=false;var s=new FishingSession(f,()=>0,()=>Observation(0),null,new InputFailureLatch());Reject(()=>s.Start(p));Assert(f.Downs==0&&!s.IsActive,"unconfirmed stationary calibration armed");});
        Test("five second countdown emits no fishing key",delegate{var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>Observation(time),null,new InputFailureLatch());s.Start(Plan());time=4999;s.Tick();Assert(f.Downs==0&&s.IsActive,"countdown");s.Stop("cleanup");});
        Test("normal cast is a bounded owned pulse then release",delegate{var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>Observation(time),null,new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();Assert(f.Downs==1&&s.IsHolding,"cast missing");time=5100;s.Tick();Assert(f.Ups==1&&!s.IsHolding,"cast did not release");s.Stop("cleanup");});
        Test("F12 cancels countdown and never rearms itself",delegate{var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>Observation(time),null,new InputFailureLatch());s.Start(Plan());f.Emergency=true;s.Tick();f.Emergency=false;time=6000;s.Tick();Assert(!s.IsActive&&f.Downs==0,"emergency rearmed");});
        Test("held Ctrl Alt or Shift cancels countdown without releasing the user modifier",delegate{foreach(ushort modifier in new ushort[]{16,17,18}){var f=new Fake{HeldModifier=modifier};long time=0;var s=new FishingSession(f,()=>time,()=>Observation(time),null,new InputFailureLatch());s.Start(Plan());time=100;s.Tick();Assert(!s.IsActive&&f.Downs==0&&f.Ups==0&&f.HeldModifier==modifier,"countdown accepted or released a user modifier");}});
        Test("modifier pressed during a fishing pulse releases only the owned fishing key",delegate{var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>Observation(time),null,new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();f.HeldModifier=16;time=5010;s.Tick();Assert(!s.IsActive&&f.Downs==1&&f.Ups==1&&f.ModifierUps==0&&f.HeldModifier==16,"held modifier was combined with input or released by the tool");});
        Test("a modifier appearing during final observation prevents pending key down",delegate{var f=new Fake();long time=0;int reads=0;var s=new FishingSession(f,()=>time,()=>{if(time>=5000&&++reads==3)f.HeldModifier=17;return Observation(time);},null,new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();Assert(!s.IsActive&&f.Downs==0&&f.Ups==0&&f.HeldModifier==17,"final modifier was combined with a fishing key");});
        Test("focus loss releases the active fishing key once",delegate{var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>Observation(time),null,new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();f.Focus=false;s.Tick();s.Stop("again");Assert(!s.IsActive&&f.Downs==1&&f.Ups==1,"focus loss release");});
        Test("stale cached observation cannot emit or keep fishing input",delegate{var f=new Fake();long time=0;var o=Observation(0);var s=new FishingSession(f,()=>time,()=>o,null,new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();Assert(!s.IsActive&&f.Downs==0,"stale cache was used");});
        Test("lost audio cannot conceal an active input pulse",delegate{var f=new Fake();long time=0;bool audio=true;var s=new FishingSession(f,()=>time,()=>{var o=Observation(time);o.AudioReady=audio;return o;},null,new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();audio=false;s.Tick();Assert(!s.IsActive&&f.Ups==1,"audio loss ignored");});
        Test("log callback cancellation before cast cannot emit orphan down",delegate{var f=new Fake();long time=0;FishingSession s=null;s=new FishingSession(f,()=>time,()=>Observation(time),message=>{if(message.StartsWith("Fishing pulse"))s.Stop("cancelled");},new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();Assert(!s.IsActive&&f.Downs==0,"log cancellation emitted input");});
        Test("partial key-down failure releases once and shares fault latch",delegate{var f=new Fake{FailDown=true};long time=0;var latch=new InputFailureLatch();var s=new FishingSession(f,()=>time,()=>Observation(time),null,latch);s.Start(Plan());time=5000;s.Tick();Assert(!s.IsActive&&latch.Faulted&&f.Downs==1&&f.Ups==1,"partial key was not released");});
        Test("user held fishing key is never tool-owned or released",delegate{var f=new Fake{Held=true};long time=0;var s=new FishingSession(f,()=>time,()=>Observation(time),null,new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();Assert(!s.IsActive&&f.Downs==0&&f.Ups==0,"user key ownership");});
        Test("map change in final reader callback prevents key down",delegate{var f=new Fake();long time=0;int reads=0;var s=new FishingSession(f,()=>time,()=>{var o=Observation(time);if(time>=5000&&++reads>=2)o.Game.Farm.MapId=43;return o;},null,new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();Assert(!s.IsActive&&f.Downs==0,"changed map emitted input");});
        Test("shared input fault blocks replacement fishing session",delegate{var latch=new InputFailureLatch();latch.Fail("prior mode release failed");var f=new Fake();var s=new FishingSession(f,()=>0,()=>Observation(0),null,latch);Reject(()=>s.Start(Plan()));Assert(f.Downs==0,"latched failure ignored");});
        Test("arming reader cancellation cannot publish a later countdown",delegate{var f=new Fake();FishingSession s=null;s=new FishingSession(f,()=>0,()=>{s.Stop("reader cancelled arming");return Observation(0);},null,new InputFailureLatch());Reject(()=>s.Start(Plan()));Assert(!s.IsActive&&f.Downs==0,"cancelled arming published a countdown");});
        Test("arming log cannot leave an active session after a shared failure",delegate{var f=new Fake();var latch=new InputFailureLatch();var s=new FishingSession(f,()=>0,()=>Observation(0),message=>{if(message.StartsWith("Fishing session armed"))latch.Fail("arming callback fault");},latch);s.Start(Plan());Assert(!s.IsActive&&latch.Faulted&&f.Downs==0,"shared arming failure left an active countdown");});
        Test("final clock callback shared failure prevents pending key down",delegate{var f=new Fake();var latch=new InputFailureLatch();long time=0;int clocks=0;var s=new FishingSession(f,()=>{if(time>=5000&&++clocks==4)latch.Fail("final clock fault");return time;},()=>Observation(time),null,latch);s.Start(Plan());time=5000;s.Tick();Assert(latch.Faulted&&!s.IsActive&&f.Downs==0,"final shared failure emitted an orphan key");});
        Test("producer refresh during reader is checked against an updated clock",delegate{var f=new Fake();long time=0;var s=new FishingSession(f,()=>time,()=>{time++;return Observation(time);},null,new InputFailureLatch());s.Start(Plan());time=6000;s.Tick();Assert(s.IsActive&&f.Downs==1,"a legal 1ms cache refresh was mistaken for a future observation");s.Stop("cleanup");});
        Test("a failed key release latches the shared failure and never retries down",delegate{var f=new Fake{FailUp=true};long time=0;var latch=new InputFailureLatch();var s=new FishingSession(f,()=>time,()=>Observation(time),null,latch);s.Start(Plan());time=5000;s.Tick();time=5100;s.Tick();s.Tick();Assert(!s.IsActive&&latch.Faulted&&f.Downs==1&&f.Ups==1,"release failure was not latched exactly once");});
        Test("a key-down callback cancellation releases its attempted ownership",delegate{var f=new Fake();long time=0;FishingSession s=null;s=new FishingSession(f,()=>time,()=>Observation(time),null,new InputFailureLatch());f.OnDown=()=>s.Stop("backend callback cancellation");s.Start(Plan());time=5000;s.Tick();Assert(!s.IsActive&&f.Downs==1&&f.Ups==1,"callback cancellation leaked an owned fishing key");});
        Test("cast planning cannot conceal a changed fishing facing",delegate{var f=new Fake();long time=0;bool turned=false;var s=new FishingSession(f,()=>time,()=>{var o=Observation(time);if(turned)o.Game.Farm.Facing=1;return o;},message=>{if(message.StartsWith("Fishing pulse Cast"))turned=true;},new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();Assert(turned&&f.Downs==0&&!s.IsActive,"cast was sent in a changed direction");});
        Test("cast planning cannot interrupt a newly observed cast",delegate{var f=new Fake();long time=0;bool casting=false;var s=new FishingSession(f,()=>time,()=>{var o=Observation(time);o.Game.Farm.Casting=casting;return o;},message=>{if(message.StartsWith("Fishing pulse Cast"))casting=true;},new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();Assert(casting&&f.Downs==0&&!s.IsActive,"pending fishing key interrupted another cast");});
        Test("reel planning delay cannot extend the authorized splash beyond 900ms",delegate{
            var f=new Fake();long time=0;int sequence=0,afterDelayReads=0;bool delayed=false;
            var s=new FishingSession(f,()=>time,()=>{var o=Sequenced(time,ref sequence);if(time>=6000){o.LastBiteAtMs=5800;o.BiteConfidence=.98;}if(delayed&&++afterDelayReads==1)o.CapturedAtMs=6000;return o;},message=>{if(message.StartsWith("Fishing pulse Reel")&&!delayed){delayed=true;time+=2000;}},new InputFailureLatch());
            s.Start(Plan());time=5000;s.Tick();time=5100;s.Tick();time=6000;s.Tick();Assert(delayed,"did not reach reel planning");Assert(f.Downs==1&&!s.IsActive,"stale splash emitted a second key instead of stopping");s.Stop("cleanup");});
        Test("a recent splash cannot send reel after its cast deadline elapsed",delegate{var f=new Fake();long time=0;int sequence=0;bool delayed=false;var s=new FishingSession(f,()=>time,()=>{var o=Sequenced(time,ref sequence);if(time>=34800){o.LastBiteAtMs=34800;o.BiteConfidence=.98;}return o;},message=>{if(message.StartsWith("Fishing pulse Reel")){delayed=true;time+=500;}},new InputFailureLatch());s.Start(Plan());time=5000;s.Tick();time=5100;s.Tick();time=34800;s.Tick();Assert(delayed&&time==35300,"did not cross the active cast deadline");Assert(f.Downs==1&&!s.IsActive,"reel was emitted after the 30 second cast window");s.Stop("cleanup");});
        Test("travel planning callback cannot move input outside the recorded corridor",delegate{
            var f=new Fake();long time=0;int sequence=0;bool offroute=false;
            var s=new FishingSession(f,()=>time,()=>{var o=time>=5000?Full(time,ref sequence):Sequenced(time,ref sequence);if(offroute){o.Game.Farm.X=.8;o.Game.Farm.Y=.8;}return o;},message=>{if(message.StartsWith("Fishing pulse Travel"))offroute=true;},new InputFailureLatch());
            s.Start(VendorPlan());for(time=5000;time<7500&&!offroute&&s.IsActive;time+=100)s.Tick();Assert(offroute,"did not reach travel planning");Assert(f.Downs==0&&!s.IsActive,"travel sent a key outside the corridor");s.Stop("cleanup");});
        Test("owned travel key releases immediately when current position leaves corridor",delegate{
            var f=new Fake();long time=0;int sequence=0;bool offroute=false;
            var s=new FishingSession(f,()=>time,()=>{var o=time>=5000?Full(time,ref sequence):Sequenced(time,ref sequence);if(offroute){o.Game.Farm.X=.8;o.Game.Farm.Y=.8;}return o;},null,new InputFailureLatch());
            s.Start(VendorPlan());for(time=5000;time<7500&&!s.IsHolding&&s.IsActive;time+=100)s.Tick();Assert(s.IsHolding,"did not reach owned travel pulse");offroute=true;s.Tick();Assert(!s.IsActive&&!s.IsHolding&&f.Ups==1,"off-corridor travel was not stopped and released");s.Stop("cleanup");});
        Test("merchant open planning cannot interact after window identity changes",delegate{
            var p=VendorPlan(true);var f=new Fake();long time=0;int sequence=0;bool swapped=false;
            var s=new FishingSession(f,()=>time,()=>{var o=time>=5000?Full(time,ref sequence):Sequenced(time,ref sequence);var target=o.Game.Farm;target.TargetExists=target.TargetIdentityKnown=target.NameHashKnown=target.AttackabilityKnown=target.TargetDeadKnown=true;target.TargetToken=11;target.TargetNameHash=p.Vendor.NameHash;target.TargetHealth=100;if(swapped){o.Game.MerchantOpen=true;o.Game.MerchantTargetToken=22;o.Game.MerchantNameHash=TargetCatalog.HashName("Other merchant");}return o;},message=>{if(message.StartsWith("Fishing pulse OpenMerchant"))swapped=true;},new InputFailureLatch());
            s.Start(p);for(time=5000;time<8500&&!swapped&&s.IsActive;time+=100)s.Tick();Assert(swapped,"did not reach merchant-open planning");Assert(f.Downs==0&&!s.IsActive,"changed merchant window received F");s.Stop("cleanup");});
        Console.WriteLine("Fishing session tests: "+passed+" passed, "+failed+" failed. Fake keyboard backend only.");return failed==0?0:1;
    }
}
